using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.AspNetCore.Mvc.Rendering;using Microsoft.EntityFrameworkCore;using MYOB.Data;using MYOB.DTOs;using MYOB.Services;using MYOB.Support;
namespace MYOB.Pages.Operations.CustomerPayments;public class CreateModel(ApplicationDbContext db,ITransactionService transactions,IPermissionService permissions):PageModel
{[BindProperty(SupportsGet=true)]public Guid? CustomerId{get;set;}[BindProperty]public CustomerPaymentForm Item{get;set;}=new();public SelectList Customers{get;private set;}=null!;public SelectList Methods{get;private set;}=null!;public IReadOnlyList<PolicyOption> Policies{get;private set;}=[];public async Task<IActionResult> OnGetAsync(){if(!await permissions.HasAsync(User,ScreenCatalog.CustomerPayments,PermissionAction.Add))return Forbid();if(CustomerId.HasValue)Item.CustomerId=CustomerId.Value;await Load();return Page();}public async Task<IActionResult> OnPostAsync(){CustomerId=Item.CustomerId;if(!await permissions.HasAsync(User,ScreenCatalog.CustomerPayments,PermissionAction.Add))return Forbid();if(ModelState.IsValid)try{await transactions.CreateCustomerPaymentAsync(new(Item.CustomerId,Item.CustomerDeliveryId,Item.Date,Item.Amount,Item.PaymentMethodId,Item.Comments));TempData["Message"]="تم تسجيل القبض من العميل";return RedirectToPage("Index");}catch(InvalidOperationException e){ModelState.AddModelError(string.Empty,e.Message);}await Load();return Page();}private async Task Load(){Customers=new(await db.Customers.AsNoTracking().OrderBy(x=>x.Name).ToListAsync(),"Id","Name",CustomerId);Methods=new(await db.PaymentMethods.AsNoTracking().OrderBy(x=>x.Name).ToListAsync(),"Id","Name");if(CustomerId.HasValue)Policies=await transactions.GetCustomerPoliciesAsync(CustomerId.Value);}}
